# Let me count all the contradictions systematically

contradictions = []

contradictions.append({
    "constraints": ["C_3-free (no triangles)", "exactly 2 vertex-disjoint cliques of size 3"],
    "reason": "A K_3 clique IS a C_3 triangle. You cannot be C_3-free and have K_3 cliques simultaneously."
})

contradictions.append({
    "constraints": ["maximum clique size <= 2", "exactly 2 vertex-disjoint cliques of size 3"],
    "reason": "Cliques of size 3 violate maximum clique size <= 2."
})

contradictions.append({
    "constraints": ["15 vertices", "exactly 2 cliques of size 3 covering every vertex"],
    "reason": "2 × 3 = 6 vertices, but we need 15. Cannot cover all 15 vertices with only 2 triangles."
})

contradictions.append({
    "constraints": ["minimum degree >= 3", "only edges within 2 K_3 cliques"],
    "reason": "In K_3, each vertex has degree 2. With only intra-clique edges, max degree = 2 < 3."
})

print(f"Found {len(contradictions)} independent contradictions:")
for i, c in enumerate(contradictions, 1):
    print(f"\nContradiction {i}:")
    print(f"  Constraints: {c['constraints']}")
    print(f"  Reason: {c['reason']}")

print("\nConclusion: The problem is UNSATISFIABLE due to multiple irreconcilable contradictions.")
